responses.text:
{
  "outcome": "revise",
  "issues": [
    {
      "kind": "contradiction",
      "severity": "critical",
      "description": "6번 줄에서 중복 이름 신청을 거부할 때 참가 인원을 1 증가시키고 다음 정원 검사에 반영하도록 규정하여, R-2(신청/취소 실패 시 참가 명단 및 정원 계산 무변경) 및 승인된 제약 조건(인원은 실제 참가 명단과 일치)과 정면으로 모순됩니다.",
      "suggestedDirection": "중복 신청 거부 시 참가 인원을 증가시키는 예외 규칙을 삭제하고, 모든 신청/취소 실패 시 명단과 인원 계산이 전혀 변경되지 않도록 단일화하십시오.",
      "relatedRequirementId": "R-2"
    }
  ],
  "suggestions": [
    "실패 시 인원을 조작하지 않고 명단의 실제 길이를 유일한 인원 계산 기준으로 유지하십시오."
  ],
  "scopeViolation": true,
  "userJudgmentRequired": false,
  "qualityAssessment": {
    "version": 1,
    "requirements": [
      {
        "requirementId": "R-1",
        "status": "satisfied",
        "evidenceLines": [3, 5],
        "rationale": "정원 2명 제한과 중복 이름 거부 규칙 및 실패 시 기존 명단 유지 요구사항이 계획에 충실히 명시되어 있습니다."
      },
      {
        "requirementId": "R-2",
        "status": "missing",
        "evidenceLines": [6],
        "rationale": "중복 이름 거부 시 참가 인원을 1 증가시키는 규칙이 포함되어 신청 실패 시 명단과 정원 계산을 변경하지 않아야 한다는 R-2 요구사항을 충족하지 못합니다."
      }
    ],
    "checks": [
      {
        "id": "decision_provenance",
        "status": "satisfied",
        "evidenceLines": [8],
        "rationale": "Scope 확정 규칙과 설계 제안 구분이 명확히 분류되어 있으며 사용자의 결정을 위조하지 않았습니다."
      },
      {
        "id": "scope_compliance",
        "status": "missing",
        "evidenceLines": [6],
        "rationale": "인원이 실제 참가 명단과 일치해야 한다는 승인된 기술 제약 조건을 위반하는 인원 증가 규칙이 포함되어 있습니다."
      },
      {
        "id": "behavior_and_errors",
        "status": "missing",
        "evidenceLines": [3, 5, 6],
        "rationale": "3번 줄 및 5번 줄의 '실패 시 무변경/명단 길이로 인원 계산' 규칙과 6번 줄의 '중복 거부 시 인원 1 증가' 규칙이 상호 모순됩니다."
      },
      {
        "id": "data_integrity",
        "status": "missing",
        "evidenceLines": [5, 6],
        "rationale": "인원 수와 실제 명단 항목 수 사이의 일관성 불변식이 중복 거부 시 깨지게 설계되어 있습니다."
      },
      {
        "id": "acceptance_criteria",
        "status": "satisfied",
        "evidenceLines": [3, 5, 8],
        "rationale": "정상 추가, 정원 초과, 중복 신청, 취소 실패 등에 대한 구체적인 입력과 기대 결과가 명시되어 있습니다."
      },
      {
        "id": "revision_resolution",
        "status": "not_applicable",
        "evidenceLines": [],
        "rationale": "검토 대상 프로젝트에 등록된 이전 수정 요청이나 확정 결정 사항이 없습니다."
      },
      {
        "id": "clarity",
        "status": "missing",
        "evidenceLines": [3, 6],
        "rationale": "이용 예시의 실패 시 무변경 진술과 규칙 절의 인원 증가 진술이 충돌하여 규칙이 모호합니다."
      }
    ]
  }
}
